from collections import Counter

def calculate_odd_frequency_residues(n):
    N = 2 * n + 1
    residues = []
    for k in range(1, N + 1):
        # P_k = (k(k+1)/2 - 1) mod (2n+1)
        pk = (k * (k + 1) // 2 - 1) % N
        residues.append(pk)

    counts = Counter(residues)
    odd_frequency_count = 0
    for count in counts.values():
        if count % 2 != 0:
            odd_frequency_count += 1
    return odd_frequency_count

# Calculate for n=1 through n=5
results = {}
for n in range(1, 6):
    results[n] = calculate_odd_frequency_residues(n)

print(results)

